{
  "schemaVersion": "0.2",
  "slug": "statistic",
  "name": "Statistic",
  "family": "D",
  "status": "experimental",
  "purpose": "Displays a single prominent metric with label, value, and optional trend indicator.",
  "scenarios": [
    "Show revenue on a dashboard",
    "Display active user count",
    "Present conversion rate with trend"
  ],
  "props": {
    "label": {
      "type": "string",
      "required": true,
      "description": "Metric label."
    },
    "value": {
      "type": "string",
      "required": true,
      "description": "Formatted metric value."
    },
    "trend": {
      "type": "enum",
      "required": false,
      "description": "Trend direction indicator.",
      "values": [
        "up",
        "down",
        "flat"
      ],
      "default": "flat"
    },
    "trendLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible description of the trend."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "trend",
      "values": [
        "up",
        "down",
        "flat"
      ],
      "default": "flat",
      "description": "Trend direction."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Metric rendered with current value."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "kpi-dashboard",
      "grid",
      "page"
    ],
    "allowedChildren": [
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not truncate the value without an accessible full form.",
    "Do not use color alone to convey trend direction."
  ],
  "a11y": {
    "role": "group",
    "keyboard": [],
    "focus": "Not focusable; purely presentational.",
    "labeling": "Label text precedes the value; trend has a text alternative.",
    "wcag": [
      "1.1.1",
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Stacks label above value; scales with type ramp.",
    "breakpoints": {
      "compact": "Compact value size.",
      "medium": "Default value size.",
      "large": "Default value size."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "statistic",
    "states": [
      "default",
      "up",
      "down",
      "flat"
    ],
    "intents": [
      "highlight-count"
    ]
  }
}

import './styles.css'

export interface StatisticProps {
  label: string
  value: string
  trend?: 'up' | 'down' | 'flat'
  trendLabel?: string
  className?: string
}

const TREND_GLYPH = { up: '▲', down: '▼', flat: '→' } as const

export function Statistic({ label, value, trend = 'flat', trendLabel, className }: StatisticProps) {
  const classes = ['cu-statistic', className].filter(Boolean).join(' ')
  return (
    <div className={classes} data-ai-role="statistic" data-ai-intent="highlight-count" data-ai-state={trend}>
      <span className="cu-statistic__label">{label}</span>
      <span className="cu-statistic__value">{value}</span>
      <span className={'cu-statistic__trend cu-statistic__trend--' + trend}>
        <span aria-hidden="true">{TREND_GLYPH[trend]}</span>
        {trendLabel ? <span className="cu-statistic__trend-sr">{trendLabel}</span> : null}
      </span>
    </div>
  )
}

.cu-statistic {
  display: inline-flex;
  flex-direction: column;
  gap: var(--cu-space-1);
  color: var(--cu-color-fg-default);
}

.cu-statistic__label {
  font-size: 0.875em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

.cu-statistic__value {
  font-size: 1.5em;
  font-weight: 600;
}

.cu-statistic__trend {
  position: relative;
}

.cu-statistic__trend--up {
  color: color-mix(in srgb, var(--cu-color-palette-brand) 60%, green);
}

.cu-statistic__trend--down {
  color: color-mix(in srgb, var(--cu-color-palette-brand) 60%, red);
}

.cu-statistic__trend--flat {
  color: var(--cu-color-border-default);
}

.cu-statistic__trend-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
